<script setup lang="ts">
import { computed } from 'vue'
import { useWorkspace } from '../composables/useWorkspace'
import StatusBadge from '../components/ui/StatusBadge.vue'
const { state, selectedIds, slots, weekStart, capacityA, capacityB, plannedMinutesA, plannedMinutesB, togglePlanIdea, createPlan } = useWorkspace()
const candidates = computed(()=>state.ideas.filter(i=>['draft','ready_for_planning'].includes(i.status)))
const priorities = computed(()=>state.plan?.slots.filter(s=>s.type==='priority')||[])
const reserves = computed(()=>state.plan?.slots.filter(s=>s.type==='reserve')||[])
function percent(value:number,capacity:number){return Math.min(100,Math.round(value/Math.max(1,capacity)*100))}
</script>
<template>
  <section class="page-section">
    <div class="page-intro-row"><div><span class="eyebrow">CAPACITY-AWARE PLANNING</span><h1>Make the week <em>work.</em></h1><p>Choose three priorities and two reserve ideas. Every minute has an owner.</p></div><span class="plan-status" v-if="state.plan">Plan saved · {{state.plan.weekStart}}</span></div>
    <div v-if="state.plan" class="saved-plan">
      <div class="section-heading"><div><span class="eyebrow">CURRENT WEEK</span><h2>Your publishing mix</h2><p>Saved plan with explicit owners and capacity estimates.</p></div><span class="status-badge status-approved">Saved plan</span></div>
      <div class="capacity-grid"><article v-for="person in (['A','B'] as const)" :key="person" class="capacity-card"><div class="capacity-head"><span class="person-avatar">P{{person}}</span><div><strong>Person {{person}}</strong><small>Weekly availability</small></div><strong class="capacity-total">{{state.plan.allocatedMinutes[person]}} / {{state.plan.capacity[person]}} min</strong></div><div class="progress-track"><i :style="{width:percent(state.plan.allocatedMinutes[person],state.plan.capacity[person])+'%'}"></i></div><small>{{Math.max(0,state.plan.capacity[person]-state.plan.allocatedMinutes[person])}} minutes remaining</small></article></div>
      <div class="saved-slots"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">01 · PRIORITY</span><h3>Must-publish ideas</h3></div><span class="slot-count">{{priorities.length}} / 3</span></div><div v-for="slot in priorities" :key="slot.ideaId" class="slot-row"><span class="slot-dot priority-dot"></span><div><strong>{{slot.title || state.ideas.find(i=>i.id===slot.ideaId)?.title || 'Content idea'}}</strong><small>Person {{slot.assignee}} · {{slot.estimatedMinutes}} min</small></div><StatusBadge status="ready_for_planning"/></div></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">02 · RESERVE</span><h3>Backup ideas</h3></div><span class="slot-count">{{reserves.length}} / 2</span></div><div v-for="slot in reserves" :key="slot.ideaId" class="slot-row"><span class="slot-dot reserve-dot"></span><div><strong>{{slot.title || state.ideas.find(i=>i.id===slot.ideaId)?.title || 'Content idea'}}</strong><small>Person {{slot.assignee}} · {{slot.estimatedMinutes}} min</small></div><StatusBadge status="ready_for_planning"/></div></section></div>
    </div>
    <div class="planner-builder">
      <div class="section-heading"><div><span class="eyebrow">PLAN BUILDER</span><h2>{{state.plan?'Create another weekly plan':'Build your weekly plan'}}</h2><p>Select exactly five ideas. First three become priorities; the last two are reserves.</p></div></div>
      <div class="planner-settings"><label class="field"><span>Week starting</span><input v-model="weekStart" type="date"/></label><label class="field"><span>Person A capacity (minutes)</span><input v-model.number="capacityA" type="number" min="0"/></label><label class="field"><span>Person B capacity (minutes)</span><input v-model.number="capacityB" type="number" min="0"/></label></div>
      <div class="capacity-grid"><article class="capacity-card"><div class="capacity-head"><span class="person-avatar">PA</span><div><strong>Person A</strong><small>{{plannedMinutesA}} / {{capacityA}} min allocated</small></div><strong>{{percent(plannedMinutesA,capacityA)}}%</strong></div><div class="progress-track"><i :class="{over:plannedMinutesA>capacityA}" :style="{width:percent(plannedMinutesA,capacityA)+'%'}"></i></div></article><article class="capacity-card"><div class="capacity-head"><span class="person-avatar">PB</span><div><strong>Person B</strong><small>{{plannedMinutesB}} / {{capacityB}} min allocated</small></div><strong>{{percent(plannedMinutesB,capacityB)}}%</strong></div><div class="progress-track"><i :class="{over:plannedMinutesB>capacityB}" :style="{width:percent(plannedMinutesB,capacityB)+'%'}"></i></div></article></div>
      <div class="candidate-list"><label v-for="idea in candidates" :key="idea.id" class="candidate-row" :class="{selected:selectedIds.includes(idea.id)}"><input type="checkbox" :checked="selectedIds.includes(idea.id)" @change="togglePlanIdea(idea.id)"/><span class="candidate-check">✓</span><span class="candidate-copy"><strong>{{idea.title}}</strong><small>{{idea.topic}}</small></span><span class="candidate-status"><StatusBadge :status="idea.status"/></span><select v-if="selectedIds.includes(idea.id)" v-model="slots[idea.id].assignee" aria-label="Assignee"><option value="A">Person A</option><option value="B">Person B</option></select><label v-if="selectedIds.includes(idea.id)" class="minutes-control"><input v-model.number="slots[idea.id].minutes" type="number" min="1" max="600"/><small>min</small></label></label><div v-if="!candidates.length" class="empty-state"><h3>No draft ideas available</h3><p>Generate ideas or add content to your library first.</p><RouterLink to="/ideas" class="button button-primary">Open content studio</RouterLink></div></div>
      <div class="planner-footer"><span>{{selectedIds.length}} of 5 selected <small>· 3 priority + 2 reserve</small></span><button class="button button-primary" :disabled="state.saving || selectedIds.length!==5 || plannedMinutesA>capacityA || plannedMinutesB>capacityB" @click="createPlan">{{state.saving?'Saving plan…':'Save weekly plan ↗'}}</button></div>
    </div>
  </section>
</template>
